// Bounded TAR parsing: never extract arbitrary paths or load an entire archive into RAM.
struct APITarEntry {let name:String;let offset:UInt64;let size:Int}
enum APITar {
    static func entries(_ url:URL)throws->[APITarEntry]{let file=try FileHandle(forReadingFrom:url);defer{try? file.close()};let end=try file.seekToEnd();try file.seek(toOffset:0);var records:[APITarEntry]=[];var names=Set<String>()
        while try file.offset()<end{let header=try file.read(upToCount:512) ?? Data();guard header.count==512 else{throw APIError.local("Neúplný TAR archiv.")};if header.allSatisfy({$0==0}){break};func text(_ range:Range<Int>)->String{String(decoding:header[range].prefix(while:{$0 != 0}),as:UTF8.self).trimmingCharacters(in:.whitespacesAndNewlines)};let name=text(0..<100),prefix=text(345..<500);guard prefix.isEmpty,(name=="manifest.json" || (name.hasPrefix("parts/") && name.hasSuffix(".bin") && name.dropFirst(6).dropLast(4).allSatisfy(\.isNumber))),names.insert(name).inserted,header[156]==0 || header[156]==48,let size=Int(text(124..<136),radix:8),size>=0,size<=16*1024*1024,let check=Int(text(148..<156),radix:8)else{throw APIError.local("Nepodporovaná nebo nebezpečná položka archivu.")};let sum=header.enumerated().reduce(0){$0 + ((148..<156).contains($1.offset) ? 32 : Int($1.element))}
            guard sum==check else{throw APIError.local("Kontrolní součet archivu nesouhlasí.")};let offset=try file.offset();guard offset+UInt64(size)<=end else{throw APIError.local("Archiv je poškozený.")};records.append(APITarEntry(name:name,offset:offset,size:size));guard records.count<=100001 else{throw APIError.local("Archiv obsahuje příliš mnoho částí.")};try file.seek(toOffset:offset+UInt64((size+511)/512*512))
        };guard records.contains(where:{$0.name=="manifest.json"})else{throw APIError.local("V archivu chybí manifest.")};return records
    }
    static func read(_ entry:APITarEntry,url:URL)throws->Data{let file=try FileHandle(forReadingFrom:url);defer{try? file.close()};try file.seek(toOffset:entry.offset);let bytes=try file.read(upToCount:entry.size) ?? Data();guard bytes.count==entry.size else{throw APIError.local("Neúplná část archivu.")};return bytes}
}
struct APIBackupsView:View {
    @ObservedObject var store:APIStore
    @State private var value:APIValue = .null
    @State private var busy=false
    @State private var problem:String?
    @State private var share:APIFile?
    @State private var importing=false
    @State private var passphrase=""
    @State private var kit:APIValue = .null
    @State private var importingKit=false
    @State private var confirmation=""
    @State private var restoring:APIValue = .null
    @State private var restorePrompt=false
    var body:some View{List{if store.owner{Section{Text("Úplná záloha obsahuje šifrovanou databázi a soubory. Obnova je povolená pouze do prázdné instalace stejného vlastníka.").font(.footnote);Button("Vytvořit úplnou zálohu"){Task{await create()}}.disabled(!value["encryptionReady"].bool || busy);Button("Importovat úplnou zálohu (.tar)"){importing=true}.disabled(busy)}
        Section("Zálohy"){ForEach(value["backups"].array,id:\.id){record in DisclosureGroup(APIFormat.date(record["createdAt"])+" · "+record["state"].string){APIDataPairs(value:record,labels:["companyName":"Firma","tables":"Tabulky","files":"Soubory","parts":"Části","bytes":"Velikost (B)","error":"Problém"]);if ["building","verifying","restoring"].contains(record["state"].string){Button("Pokračovat v přípravě"){Task{await advance(record.id)}}};if ["ready","restored"].contains(record["state"].string){Button("Stáhnout a sdílet archiv"){Task{await download(record.id)}};if value["empty"].bool{Button("Obnovit tuto zálohu"){restoring=record;confirmation="";restorePrompt=true}}}}}}
        Section("Obnovovací klíč"){SecureField("Heslo k obnovovacímu balíčku",text:$passphrase).textContentType(.newPassword);Button("Vytvořit a exportovat balíček"){Task{await recovery()}}.disabled(busy);Button("Načíst balíček pro import"){importingKit=true};if !kit.isNull{Text("Obnovovací balíček je načtený pouze v paměti.").font(.footnote)}}
    }else{Text("Úplné zálohy jsou dostupné pouze vlastníkovi firmy.")};if busy{ProgressView("Probíhá operace…")};if let problem{Text(problem).foregroundStyle(DiaryStyle.warning)}}.navigationTitle("Úplné zálohy").task{await load()}.refreshable{await load()}.sheet(item:$share){FileShare(url:$0.url)}.alert("Obnovit do prázdné instalace",isPresented:$restorePrompt){TextField("Napište OBNOVIT",text:$confirmation);Button("Obnovit",role:.destructive){Task{await restore()}};Button("Zrušit",role:.cancel){}}message:{Text("Zdroj: "+restoring["companyName"].string+". Cíl: "+store.company+". Provozní data server nepřepíše.")}.fileImporter(isPresented:$importing,allowedContentTypes:[.data]){result in Task{do{let url=try result.get();let access=url.startAccessingSecurityScopedResource();defer{if access{url.stopAccessingSecurityScopedResource()}};await importArchive(url)}catch{problem=error.localizedDescription}}}.fileImporter(isPresented:$importingKit,allowedContentTypes:[.json]){result in do{let url=try result.get();let access=url.startAccessingSecurityScopedResource();defer{if access{url.stopAccessingSecurityScopedResource()}};let bytes=try Data(contentsOf:url);guard bytes.count<1024*1024 else{throw APIError.local("Neplatný obnovovací balíček.")};kit=try JSONDecoder().decode(APIValue.self,from:bytes)}catch{problem=error.localizedDescription}}}
    func load()async{guard store.owner else{return};do{value=try await store.get("/api/system-backups")}catch{problem=error.localizedDescription}}
    func create()async{busy=true;defer{busy=false};do{let id=UUID().uuidString;_ = try await store.write("/api/system-backups",method:"POST",body:.object(["id":.s(id)]));await advance(id)}catch{problem=error.localizedDescription}}
    func advance(_ id:String)async{busy=true;defer{busy=false};do{for _ in 0..<5000{try Task.checkCancellation();let result=try await store.write("/api/system-backups/"+id+"/step",method:"POST",body:.object([:]));if !["building","verifying","restoring"].contains(result["state"].string){break};try await Task.sleep(for:.milliseconds(100))};await load()}catch{problem=error.localizedDescription;await load()}}
    func download(_ id:String)async{busy=true;defer{busy=false};do{let url=try await store.transport.download("/api/system-backups/"+id+"/download");share=APIFile(url:url)}catch{problem=error.localizedDescription}}
    func recovery()async{busy=true;defer{busy=false;passphrase=""};do{let result=try await store.write("/api/system-backups/recovery-kit",method:"POST",body:.object(["passphrase":.s(passphrase)]));share=APIFile(url:APIImage.temporary(try result.data(),name:"Obnovovaci-klic.json"))}catch{problem=error.localizedDescription}}
    func importArchive(_ url:URL)async{busy=true;defer{busy=false;passphrase="";kit = .null};do{let entries=try APITar.entries(url);let manifest=entries.first{$0.name=="manifest.json"}!;var envelope=try JSONDecoder().decode(APIValue.self,from:APITar.read(manifest,url:url));if !kit.isNull{envelope["recoveryKit"]=kit;envelope["passphrase"] = .s(passphrase)};let imported=try await store.write("/api/system-backups/import",method:"POST",body:envelope);let id=imported.id.isEmpty ? envelope.id : imported.id;for part in entries where part.name != "manifest.json"{try Task.checkCancellation();let index=part.name.dropFirst(6).dropLast(4);try await store.upload("/api/system-backups/"+id+"/parts/"+index,bytes:APITar.read(part,url:url),type:"application/octet-stream")};_ = try await store.write("/api/system-backups/"+id+"/verify",method:"POST",body:.object([:]));await advance(id)}catch{problem=error.localizedDescription;await load()}}
    func restore()async{guard confirmation=="OBNOVIT" else{problem="Potvrzovací text nesouhlasí.";return};do{_ = try await store.write("/api/system-backups/"+restoring.id+"/restore",method:"POST",body:.object(["confirm":.s(confirmation),"sourceInstanceId":restoring["instanceId"],"targetInstanceId":value["installation"]["id"]]));await advance(restoring.id)}catch{problem=error.localizedDescription}}
}
